export const secureSessionStorage: SessionStorage = {
  getToken() {
    return SecureStore.getItemAsync(SESSION_TOKEN_KEY);
  },
  setToken(token) {
    return SecureStore.setItemAsync(SESSION_TOKEN_KEY, token, {
